#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8
FAIL=0
START_TS=0
declare -A RESULT=()
[[ "$ENV_FILE" == ".env" ]] && ENV_FILE=".env.ui-verify"   # 不污染工程 .env
sha() { if command -v sha256sum >/dev/null 2>&1; then sha256sum "$@"; else shasum -a 256 "$@"; fi; }

banner "换壳发布验收（真机两项人工门）"

# ── 1. 定位环境 ───────────────────────────────────────────────────────────
stage "定位仓库 / 本包 / dsh 安装 / profile"
say "这个向导只读路径、不搬文件；值会记到 .env.ui-verify，重跑时回车沿用。"
note "仓库根：含 Plugins/DSHClientUILauncher 的目录"
ask REPO_DIR "仓库根目录："
REPO_DIR=${REPO_DIR:-$PWD}
ask PACKAGE_DIR "本包目录（默认 <仓库>/Plugins/DSHClientUILauncher）："
PACKAGE_DIR=${PACKAGE_DIR:-$REPO_DIR/Plugins/DSHClientUILauncher}
ask DSH_INSTALL "dsh 安装目录（含 lib/bin.js）："
ask DSH_BIN "dsh 可执行文件路径（没有就回车跳过，stage 4 会 exit 3 跳过）："
ask PROFILE_SRC "要验的 dsh profile 目录（默认 ~/.dsh/profiles/web）："
PROFILE_SRC=${PROFILE_SRC:-$HOME/.dsh/profiles/web}

[ -f "$PACKAGE_DIR/package.json" ] || { warn "PACKAGE_DIR 不是有效包：$PACKAGE_DIR"; exit 2; }
[ -f "$DSH_INSTALL/lib/bin.js" ] || { warn "DSH_INSTALL 下没有 lib/bin.js：$DSH_INSTALL"; exit 2; }
[ -f "$PROFILE_SRC/package.json" ] || { warn "PROFILE_SRC 不是有效 profile：$PROFILE_SRC"; exit 2; }

write_env REPO_DIR "$REPO_DIR"
write_env PACKAGE_DIR "$PACKAGE_DIR"
write_env DSH_INSTALL "$DSH_INSTALL"
write_env DSH_BIN "$DSH_BIN"
write_env PROFILE_SRC "$PROFILE_SRC"
DSH_CMD=${DSH_BIN:-dsh}
RESULT[1]="OK 路径与包都校验通过"

# ── 2. 备份 profile + 数据指纹 ────────────────────────────────────────────
stage "备份 profile，记录数据指纹（回退前后要逐字比对）"
BACKUP="$PROFILE_SRC.bak.$(date +%Y%m%d-%H%M%S)"
say "备份 profile 到：$BACKUP"
cp -a "$PROFILE_SRC" "$BACKUP"
FINGERPRINT_FILE=/tmp/dsh-rollback-fingerprints.txt
step "记录 approval-policy.json / approval-audit.jsonl / pnpm-lock.yaml 的 sha256"
if [ -f "$HOME/.dsh/state/approval-policy.json" ] || [ -f "$HOME/.dsh/state/approval-audit.jsonl" ]; then
  sha "$HOME/.dsh/state/approval-policy.json" "$HOME/.dsh/state/approval-audit.jsonl" "$PROFILE_SRC/pnpm-lock.yaml" > "$FINGERPRINT_FILE" 2>/dev/null || true
else
  warn "没找到 ~/.dsh/state 下的审批数据；只记 pnpm-lock.yaml"
  sha "$PROFILE_SRC/pnpm-lock.yaml" > "$FINGERPRINT_FILE" 2>/dev/null || true
fi
note "指纹写到：$FINGERPRINT_FILE"
write_env BACKUP_DIR "$BACKUP"
write_env FINGERPRINT_FILE "$FINGERPRINT_FILE"
RESULT[2]="OK 已备份 + 指纹已记录（$FINGERPRINT_FILE）"

# ── 3. 独立实例验换壳（不碰在用 dsh） ────────────────────────────────────
stage "独立实例验一次换壳（verify-shell-standalone.sh launcher）"
say "这一步起一个独立端口的 dsh，不碰你正在用的实例。"
if DSH_INSTALL="$DSH_INSTALL" PROFILE_SRC="$PROFILE_SRC" PACKAGE_DIR="$PACKAGE_DIR" \
     "$PACKAGE_DIR/scripts/verify-shell-standalone.sh" launcher; then
  RESULT[3]="PASS 独立实例换壳：__DSH_LAUNCHER_SHELL__===true、data-shell=launcher 在"
else
  RESULT[3]="FAIL 独立实例换壳断言失败（看上面的输出）"; FAIL=1
fi
pause "看完输出，回车继续"

# ── 4. 真机 canary --real ────────────────────────────────────────────────
stage "真机 canary：--real --mode both"
if [ -z "$DSH_BIN" ]; then
  warn "没有提供 DSH_BIN，跳过真机 canary（不假装成功）"
  RESULT[4]="SKIP 无 DSH_BIN，真机 canary 未跑"
else
  set +e
  DSH_BIN="$DSH_BIN" DSH_INSTALL="$DSH_INSTALL" node "$PACKAGE_DIR/scripts/canary.mjs" --real --mode both
  RC=$?
  set -e
  case "$RC" in
    0) RESULT[4]="PASS canary --real 两条路径通过" ;;
    3) RESULT[4]="SKIP canary --real 环境缺件（exit 3），真机证据仍缺"; warn "canary 跳过：环境缺件" ;;
    *) RESULT[4]="FAIL canary --real 断言失败（exit $RC）"; FAIL=1 ;;
  esac
fi
pause "回车继续"

# ── 5. 三态起点：native ──────────────────────────────────────────────────
stage "态 1/3 · native 起点核对"
say "打开 dsh web，按 devtools console 核这两个特征："
step "window.__DSH_LAUNCHER_SHELL__ 不是 true（undefined/false）"
step "document.querySelector('[data-shell=\"launcher\"]') === null 且 [data-slot=\"root\"] 在"
confirm "确认当前是 native 态？" && RESULT[5]="PASS native 起点已核对" || { RESULT[5]="FAIL native 起点不符"; FAIL=1; }

# ── 6. 切到 launcher ─────────────────────────────────────────────────────
stage "态 2/3 · native → launcher"
say "把本包按 file: 依赖装进 profile（不改 ~/.dsh 里的文件，只走 dsh plugin 接口）。"
if confirm "现在执行 dsh plugin add？"; then
  set +e
  "$DSH_CMD" plugin --profile web add "@deepseek-ai/dsh-client-ui-layout@file:$PACKAGE_DIR"
  RC=$?
  set -e
  [ $RC -eq 0 ] && note "装完请重启 dsh web 并硬刷新页面" || { warn "plugin add 退出码 $RC"; FAIL=1; }
  pause "重启并硬刷新后回车"
  step "核对：__DSH_LAUNCHER_SHELL__ === true 且 [data-shell=\"launcher\"] 在、无 #launcher-hostguard-banner"
  step "核对：设置 → 高级 有「回退原生 UI」与可复制命令"
  confirm "launcher 态两项都通过？" && RESULT[6]="PASS 切到 launcher 成功" || { RESULT[6]="FAIL launcher 态不符"; FAIL=1; }
else
  RESULT[6]="SKIP 未执行切换"; warn "跳过态 2"
fi

# ── 7. 回退 native + 指纹比对 + 3 分钟 ───────────────────────────────────
stage "态 3/3 · launcher → native（回退）"
say "三条命令与产品里「回退原生 UI」展示的同源（remove → install → 重启）："
note "  ${DSH_BIN:-dsh} plugin --profile web remove @deepseek-ai/dsh-client-ui-layout"
note "  ${DSH_BIN:-dsh} plugin --profile web install"
note "  重启 dsh web 并硬刷新"
if confirm "现在执行回退？这会摘掉换壳依赖（数据不动）"; then
  START_TS=$(date +%s)
  set +e
  "$DSH_CMD" plugin --profile web remove @deepseek-ai/dsh-client-ui-layout && "$DSH_CMD" plugin --profile web install
  RC=$?
  set -e
  [ $RC -eq 0 ] && note "回退命令完成，请重启并硬刷新" || { warn "回退命令退出码 $RC"; FAIL=1; }
  pause "重启并硬刷新后回车"
  step "核对：__DSH_LAUNCHER_SHELL__ 不为 true、[data-shell=\"launcher\"] 不在、[data-slot=\"root\"] 在"
  confirm "已回到 native 态？" && RESULT[7]="PASS 回退到 native" || { RESULT[7]="FAIL 未回到 native"; FAIL=1; }
  ELAPSED=$(( $(date +%s) - START_TS ))
  if [ "$ELAPSED" -le 180 ]; then note "耗时 ${ELAPSED}s（≤180s 达标）"; else warn "耗时 ${ELAPSED}s 超过 3 分钟"; RESULT[7]="${RESULT[7]} · 超时 ${ELAPSED}s"; FAIL=1; fi
  step "比对数据指纹（应与 stage 2 逐字一致）："
  if [ -f "$FINGERPRINT_FILE" ]; then
    if sha -c "$FINGERPRINT_FILE" 2>/dev/null; then note "指纹一致（审批策略/审计/lock 未变）"; else warn "指纹不一致，请人工核对"; FAIL=1; fi
  fi
else
  RESULT[7]="SKIP 未执行回退"; warn "跳过态 3"
fi

# ── 8. 汇总 ──────────────────────────────────────────────────────────────
stage "汇总"
for i in 1 2 3 4 5 6 7; do printf '  %s\n' "${RESULT[$i]:-（未执行）}"; done
if [ "$FAIL" -eq 0 ]; then
  printf '\n%s✓ 全部通过：可进入 PR / 发布%s\n' "$BOLD$GREEN" "$RESET"
else
  printf '\n%s✗ 有未通过项，先修再发布%s\n' "$BOLD$YELLOW" "$RESET"
fi
[ -n "${DSH_BIN:-}" ] && set_var DSH_BIN "$DSH_BIN" || note "未设 DSH_BIN，CI 的 real-canary 需手动配 vars.DSH_BIN"

finish
[ "$FAIL" -eq 0 ] || exit 1
}

run_wizard "$@"; exit
